const fs = require('fs');

const n = Number(fs.readFileSync(0, 'utf8').trim());
const size = n + 1;
const dp = new Float64Array(size * size);

for (let gap = 2; gap < n; gap++) {
    for (let left = 1; left + gap <= n; left++) {
        const right = left + gap;
        const base = left * right;
        let best = Infinity;

        for (let mid = left + 1; mid < right; mid++) {
            const cost =
                dp[left * size + mid] +
                dp[mid * size + right] +
                base * mid;

            if (cost < best) best = cost;
        }

        dp[left * size + right] = best;
    }
}

console.log(dp[size + n].toString());

const fs = require('fs');

const n = Number(fs.readFileSync(0, 'utf8').trim());
const dp = new Float64Array(n * n);

for (let len = 2; len < n; len++) {
    for (let i = 0; i + len < n; i++) {
        const j = i + len;
        let best = Infinity;
        const productIJ = (i + 1) * (j + 1);

        for (let k = i + 1; k < j; k++) {
            const cost = dp[i * n + k] + dp[k * n + j] + productIJ * (k + 1);
            if (cost < best) best = cost;
        }

        dp[i * n + j] = best;
    }
}

console.log(dp[n - 1].toString());

